static void test_str()
{
	run_strlen();
	run_strcmp();
	run_strncmp();

	print_result(g_pass, g_fail);
}

int main()
{
	g_pass = 0;
	g_fail = 0;

	print_suite_name("STRING");
	test_str();

	return g_fail != 0;
}